import{_ as t,l as i,o as a,c as n,v as o,p as r,x as s,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"信号掩码","description":"","frontmatter":{"title":"信号掩码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sigmask.md","filePath":"cs/sigmask.md","lastUpdated":1789023840000}'),E={name:"cs/sigmask.md"};function h(m,e,A,_,g,S){const d=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="信号掩码" tabindex="-1">信号掩码 <a class="header-anchor" href="#信号掩码" aria-label="Permalink to &quot;信号掩码&quot;">​</a></h1><div class="epigraph"><p>进程或线程可以暂时阻塞某些信号：pending 仍记下，直到解除掩码才在返回用户态时递送。</p><footer>—— 据 POSIX sigprocmask / pthread_sigmask；Stevens and Rago, APUE 整理</footer></div><p><a href="/cs/signals">上一课</a>规定信号在回用户前递送，并点到阻塞集合。缺口是把 <strong>掩码</strong> 收成接口：何时必须挡住、与系统调用重启的关系、以及多线程下「谁的掩码」。不是再列默认动作。下一课管道才传字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>处理函数里若再来同一信号，可能重入不可重入库。临界区若被 <code>SIGALRM</code> 打断，用户锁会乱。<a href="/cs/lock-irq">锁</a> 在用户态不能关中断。缺口：<code>sigprocmask</code> 把集合加入 blocked；到达的被挡信号进 pending。<code>sigsuspend</code> 原子地换掩码并睡眠。<code>SA_RESTART</code> 让部分系统调用在被中断后自动再执行，否则返回 EINTR。</p><p>本课不把实时信号排队深度的全部 POSIX 条款背完。</p><p><span class="marginnote">多线程：掩码通常是线程属性；未阻塞的信号递送到某个未挡它的线程。<code>SIGKILL</code>/<code>SIGSTOP</code> 不能掩。本课不写如何用信号打探内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在 PCB/thread 里存 blocked 与 pending 位图。递送条件：pending 有、blocked 无、且到了用户边界。同步信号（如坏地址）通常不可当普通掩码永远吞掉——否则无法前进；实现上仍可能在极短窗口阻塞。<code>pselect</code>/<code>ppoll</code> 把「等 fd 与换掩码」做成原子，避免漏唤醒，后课多路复用会用到。</p>',9)),(a(),r(p,null,{default:s(()=>[c(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E4%BF%A1%E5%8F%B7%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20BLK%7B%22%E5%9C%A8%E6%8E%A9%E7%A0%81%E4%B8%AD%3F%22%7D%0A%20%20BLK%20--%3E%7C%E6%98%AF%7C%20PEND%5B%22%E5%8F%AA%E8%AE%B0%20pending%22%5D%0A%20%20BLK%20--%3E%7C%E5%90%A6%7C%20DELIV%5B%22%E5%9B%9E%E7%94%A8%E6%88%B7%E6%97%B6%E9%80%92%E9%80%81%22%5D%0A%20%20UNMASK%5B%22%E8%A7%A3%E9%99%A4%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20DELIV%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩码把信号从「随时插入」改成「可推迟的边沿」，让用户态临界区有边界。它不代替管道：pending 几乎不带负载。与内核关中断对照：对象是进程事件，不是本地 IRQ。EINTR 是系统调用路径与信号的接头，应用程序必须会处理或请求重启。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 signalfd 的全部细节，只承认信号也可变成文件描述符上的可读事件。下一课要用内核缓冲传字节，而不是一位 pending。</p><p>后课默认：信号可阻塞与推迟。亲缘进程之间的字节流，下一课管道与 IPC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>blocked 推迟递送；pending 仍保留。</li><li>EINTR 与 SA_RESTART 连接系统调用。</li><li>字节通道是管道课的缺口。</li><li>出处：POSIX signals；Stevens and Rago, <em>APUE</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const f=t(E,[["render",h]]);export{T as __pageData,f as default};
